describe('Export Personal Data as JSON File', () => {
  beforeEach(() => {
    cy.visit('/user-profile');
  });

  it('should successfully export personal data as a JSON file', () => {
    // Verify export button is visible
    cy.get('[data-testid="export-button"]').should('be.visible');

    // Click export button
    cy.get('[data-testid="export-button"]').click();

    // Verify download dialog appears
    cy.get('[data-testid="download-dialog"]').should('be.visible');

    // Verify download button is present
    cy.get('[data-testid="download-button"]').should('be.visible');

    // Click download button
    cy.get('[data-testid="download-button"]').click();

    // Verify file download dialog closes
    cy.get('[data-testid="download-dialog"]').should('not.exist');

    // Verify file appears in downloads folder
    cy.get('[data-testid="downloaded-file"]').should('be.visible');
    cy.get('[data-testid="downloaded-file"]').should('contain', 'personal-data.json');

    // Verify file size is reasonable
    cy.get('[data-testid="downloaded-file"]').should('have.attr', 'size', '>= 1000');

    // Verify file contains expected data
    cy.get('[data-testid="downloaded-file"]').then((file) => {
      const fileContent = file.get('text/plain');
      expect(fileContent).to.include('name');
      expect(fileContent).to.include('email');
      expect(fileContent).to.include('phone');
    });
  });

  it('should handle export failure and display error message', () => {
    // Mock API to simulate export failure
    cy.intercept('POST', '/api/export-data', {
      statusCode: 500,
      body: { error: 'Internal server error' }
    }).as('exportFailed');

    // Click export button
    cy.get('[data-testid="export-button"]').click();

    // Verify download dialog appears
    cy.get('[data-testid="download-dialog"]').should('be.visible');

    // Click download button
    cy.get('[data-testid="download-button"]').click();

    // Verify download dialog closes
    cy.get('[data-testid="download-dialog"]').should('not.exist');

    // Verify error message is displayed
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Failed to export data');

    // Verify export button is still available
    cy.get('[data-testid="export-button"]').should('be.visible');
  });
});
